import sys

def find_string(a_00, a_01, a_10, a_11):
    # Check if the given counts can form a valid string
    if a_00 + a_01 != a_00 + a_10 or a_01 + a_11 != a_10 + a_11:
        return "Impossible"

    # Construct the string
    result = []
    for _ in range(a_00):
        result.append("00")
    for _ in range(a_01):
        result.append("01")
    for _ in range(a_10):
        result.append("10")
    for _ in range(a_11):
        result.append("11")

    # Join the list into a single string
    return "".join(result)

# Read input
a_00, a_01, a_10, a_11 = map(int, sys.stdin.read().split())

# Find and print the result
print(find_string(a_00, a_01, a_10, a_11))
